function sha256Hex(bytes) {
  const k = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b,
    0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01,
    0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7,
    0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152,
    0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
    0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819,
    0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08,
    0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f,
    0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];

  const data = Array.from(bytes);
  const bitLength = data.length * 8;

  // Padding
  data.push(0x80);

  while ((data.length % 64) !== 56) {
    data.push(0);
  }

  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;

  for (let shift = 24; shift >= 0; shift -= 8) {
    data.push((high >>> shift) & 0xff);
  }

  for (let shift = 24; shift >= 0; shift -= 8) {
    data.push((low >>> shift) & 0xff);
  }

  // Valores iniciais SHA-256
  let h0 = 0x6a09e667;
  let h1 = 0xbb67ae85;
  let h2 = 0x3c6ef372;
  let h3 = 0xa54ff53a;
  let h4 = 0x510e527f;
  let h5 = 0x9b05688c;
  let h6 = 0x1f83d9ab;
  let h7 = 0x5be0cd19;

  for (let offset = 0; offset < data.length; offset += 64) {
    const w = new Uint32Array(64);

    for (let i = 0; i < 16; i++) {
      const j = offset + (i * 4);

      w[i] = (
        (data[j] << 24) |
        (data[j + 1] << 16) |
        (data[j + 2] << 8) |
        data[j + 3]
      ) >>> 0;
    }

    for (let i = 16; i < 64; i++) {
      const s0 =
        ((w[i - 15] >>> 7) | (w[i - 15] << 25)) ^
        ((w[i - 15] >>> 18) | (w[i - 15] << 14)) ^
        (w[i - 15] >>> 3);

      const s1 =
        ((w[i - 2] >>> 17) | (w[i - 2] << 15)) ^
        ((w[i - 2] >>> 19) | (w[i - 2] << 13)) ^
        (w[i - 2] >>> 10);

      w[i] = (
        w[i - 16] +
        s0 +
        w[i - 7] +
        s1
      ) >>> 0;
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    let f = h5;
    let g = h6;
    let h = h7;

    for (let i = 0; i < 64; i++) {
      const S1 =
        ((e >>> 6) | (e << 26)) ^
        ((e >>> 11) | (e << 21)) ^
        ((e >>> 25) | (e << 7));

      const choice =
        (e & f) ^
        ((~e) & g);

      const temp1 = (
        h +
        S1 +
        choice +
        k[i] +
        w[i]
      ) >>> 0;

      const S0 =
        ((a >>> 2) | (a << 30)) ^
        ((a >>> 13) | (a << 19)) ^
        ((a >>> 22) | (a << 10));

      const majority =
        (a & b) ^
        (a & c) ^
        (b & c);

      const temp2 = (
        S0 +
        majority
      ) >>> 0;

      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  return [
    h0,
    h1,
    h2,
    h3,
    h4,
    h5,
    h6,
    h7,
  ]
    .map((value) =>
      value
        .toString(16)
        .padStart(8, '0')
    )
    .join('');
}


// ============================================================
// 1. BUSCAR CONFIGURAÇÃO CLOUDINARY DO NODE BASE-64
// ============================================================

const cloudinary = $('BASE-64').first().json;

if (!cloudinary) {
  throw new Error(
    'Dados do node "BASE-64" não encontrados.'
  );
}

if (!cloudinary['API-USER']) {
  throw new Error(
    'API-USER não encontrado no node "BASE-64".'
  );
}

if (!cloudinary.AUTHORIZATION) {
  throw new Error(
    'AUTHORIZATION não encontrado no node "BASE-64".'
  );
}


// ============================================================
// 2. PROCESSAR IMAGENS
// ============================================================

const output = [];

for (let index = 0; index < items.length; index++) {

  const item = items[index];

  // ----------------------------------------------------------
  // Validar binary.data
  // ----------------------------------------------------------

  if (!item.binary?.data) {
    throw new Error(
      `Imagem binária "data" ausente no item ${index}.`
    );
  }


  // ----------------------------------------------------------
  // Obter conteúdo real do arquivo
  // ----------------------------------------------------------

  const buffer =
    await this.helpers.getBinaryDataBuffer(
      index,
      'data'
    );


  // ----------------------------------------------------------
  // Calcular SHA-256
  // ----------------------------------------------------------

  const sha256 = sha256Hex(buffer);


  // ----------------------------------------------------------
  // Montar item final
  // ----------------------------------------------------------

  output.push({

    // Preserva o item original,
    // inclusive binary.data
    ...item,

    json: {

      // Preserva JSON recebido da imagem
      ...item.json,


      // ======================================================
      // CLOUDINARY
      // ======================================================

      'API-USER':
        cloudinary['API-USER'],

      'API-FOLDER':
        cloudinary['API-FOLDER'] ?? null,

      AUTHORIZATION:
        cloudinary.AUTHORIZATION,


      // ======================================================
      // IMAGEM / SHA-256
      // ======================================================

      media_sha256:
        sha256,

      cloudinary_public_id:
        sha256,

      media_original_filename:
        item.binary.data.fileName ?? null,

      media_mime_type:
        item.binary.data.mimeType ?? null,
    },
  });
}


// ============================================================
// 3. RETORNO
// ============================================================

return output;

const apiKey = String($json['API-KEY'] ?? '').trim();
const apiSecret = String($json['API-SECRET'] ?? '').trim();
const apiFolder = String($json['API-FOLDER'] ?? '').trim();

if (!apiKey || !apiSecret) {
  throw new Error('API-KEY ou API-SECRET não informado');
}

// Basic Auth Cloudinary:
// API-KEY:API-SECRET
const credentials = `${apiKey}:${apiSecret}`;

const base64 = Buffer
  .from(credentials, 'utf8')
  .toString('base64');

return {
  json: {
    ...$json,

    // Mantém API-FOLDER disponível para o Upload,
    // mas NÃO inclui a pasta na autenticação
    'API-FOLDER': apiFolder,

    AUTHORIZATION: `Basic ${base64}`,
  },

  binary: $binary,
};

const items = $input.all();

// O primeiro item retornado pelo CALL contém o array com a API
const registro = items[0].json[0];

if (!registro) {
  throw new Error('A SP sp_get_api não retornou nenhuma API disponível.');
}

return [
  {
    json: registro
  }
];
